"use client";
/* Roomba, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Roomba(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("roomba"); }, []);
  return React.createElement("piix-pal", { "pal": "roomba", ...piixAttrs(props) });
}

export default Roomba;
